"""FM-16N original six-stage editorial pathways."""
import sympy as s
from calibration_bank import LEVELS,L
M=s.Matrix
h,k,t,z,u,w=s.symbols('h k t z u w',real=True)
PATHS={'matrix-add-subtract':'MAT.arithmetic.add-subtract','matrix-products':'MAT.arithmetic.multiply','vector-combinations':'VEC.3d.operations','perpendicular-test':'VEC.perpendicular.test'}
RATIONALES={
 'matrix-add-subtract':['Subtract signed scalars.','Explain the matching-dimension requirement.','Calculate a signed matrix expression entrywise.','Recover two matrices from simultaneous sum and difference constraints.','Recover two unknowns from symmetry and trace constraints.','Enrichment: prove unique symmetric/skew decomposition and classify singular symmetric parts.'],
 'matrix-products':['Calculate a row-column scalar sum.','Diagnose entrywise multiplication error.','Compute a rectangular matrix product.','Recover an unknown matrix row from a prescribed product.','Construct and check a one-sided inverse using matrix products.','Enrichment: classify all right inverses of a rectangular matrix and prove impossibility of a left inverse.'],
 'vector-combinations':['Calculate signed component arithmetic.','Diagnose inconsistent scalar multiplication.','Compute a signed linear combination of 3D vectors.','Construct a parallelogram and verify diagonals.','Recover an interior section ratio and check all components.','Enrichment: classify points in a triangular region using vector combinations and prove uniqueness.'],
 'perpendicular-test':['Calculate a scalar product.','Distinguish zero dot product from a defined right angle.','Test two candidate vectors.','Identify a right angle among all vertices of a spatial triangle.','Recover a vector perpendicular to two independent directions with a fixed component.','Classify all perpendicular nonzero pairs, excluding zero directions and forbidden divisions.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=v+3;d=2*v+5
 if path=='matrix-add-subtract':
  A=M([[a,-b],[d,1]]);B=M([[1,d],[-a,b]])
  if l==1:
   f=[-a-b];q=f'Calculate $-{a}-{b}$.';ans=L(f[0]);steps=[f'Subtract {b} from -{a} to obtain {ans}.'];hints=['Start at the negative number.','Subtracting a positive number decreases it.'];mistake='Adding the positive magnitude instead of subtracting.'
  elif l==2:
   C=M([[a,b,d],[1,0,a]]);f=[False,True,s.zeros(2,3)];q=f'Given A={L(A)} and C={L(C)}, a student says A+C exists because both have two rows. Explain whether A+C and C-C exist.';ans='A+C is undefined; C-C is defined.';steps=['Addition and subtraction require matching row AND column counts. A has two columns and C has three.',f'C-C is the 2 by 3 zero matrix {L(s.zeros(2,3))}.'];hints=['Count rows and columns.','Match entries by their positions.'];mistake='Checking only the number of rows.'
  elif l==3:
   f=[A-2*B];q=f'Calculate A-2B for A={L(A)} and B={L(B)}.';ans=L(f[0]);steps=[f'First double every entry of B to get {L(2*B)}.',f'Subtract corresponding entries from A: {ans}.'];hints=['Scale all four entries first.','Subtract negative entries carefully.'];mistake='Subtracting 2 from each entry rather than multiplying B.'
  elif l==4:
   P=A+B;Q=A-B;f=[A,B];q=f'Find X and Y satisfying X+Y={L(P)} and X-Y={L(Q)}. Verify both matrix equations.';ans=f'X={L(A)}, Y={L(B)}.';steps=[f'Add the equations: 2X={L(P+Q)}, giving X={L(A)}.',f'Subtract the second from the first: 2Y={L(P-Q)}, giving Y={L(B)}.',f'Adding and subtracting the results gives {L(P)} and {L(Q)} respectively; the operations are reversible.'];hints=['Add the two equations to eliminate Y.','Subtract to eliminate X.'];mistake='Dividing the sum or difference by only one entry.'
  elif l==5:
   C=M([[h,a],[b,k]]);D=M([[d,k],[h,1]]);H=s.Rational(2*b-a+d,2);K=H+b-a;target=H+K+d+1;S=(C+D).subs({h:H,k:K});f=[H,K,S];q=f'Let A={L(C)} and B={L(D)}. Determine h,k such that A+B is symmetric and its diagonal entries sum to {L(target)}. Give A+B and justify uniqueness.';ans=f'h={L(H)}, k={L(K)}, A+B={L(S)}.';steps=[f'Symmetry of A+B requires {a}+k={b}+h, so k=h+{b-a}.',f'The sum of diagonal entries requires h+k={L(target-d-1)}.',f'Substitute the first equation into the second to obtain {ans} Both constraints hold and the linear equation has nonzero coefficient.'];hints=['Compare the off-diagonal entries.','Use the diagonal sum as a second equation.'];mistake='Demanding A and B separately be symmetric.'
  else:
   C=M([[a,h],[k,b]]);S=(C+C.T)/2;K=(C-C.T)/2;r=2*s.sqrt(a*b);f=[S,K,r,-r];q=f'For all real h,k write A={L(C)} as S+K where S is symmetric and K satisfies K^T=-K. Prove the decomposition is unique and determine exactly when S is singular.';ans=f'S={L(S)}, K={L(K)}; S is singular iff h+k={L(r)} or h+k={L(-r)}.';steps=['Transpose A=S+K to obtain A^T=S-K. Add and subtract these equations to force S=(A+A^T)/2 and K=(A-A^T)/2.',f'This gives {L(S)} and {L(K)}. Direct addition and transposition verify both properties, so the forced decomposition exists and is unique.',f'The determinant of S is {L(s.expand(S.det()))}. Thus singularity is equivalent to (h+k)^2={4*a*b}.',f'The two real branches are h+k={L(r)} and h+k={L(-r)}. Both make the determinant zero; no other value can do so.'];hints=['Transpose the given decomposition.','Use addition and subtraction to isolate the two parts, then calculate the determinant.'];mistake='Assuming the skew-symmetric part is zero or keeping only one square-root branch.'
 elif path=='matrix-products':
  A=M([[a,1,-b],[1,d,2]]);B=M([[1,a],[b,-1],[d,2]])
  if l==1:
   f=[a+b*d];q=f'Find the sum of products of corresponding entries of the row (1,{b}) and column ({a},{d})^T.';ans=L(f[0]);steps=[f'Calculate 1 times {a} plus {b} times {d}: {ans}.'];hints=['Pair the first entries.','Add both products.'];mistake='Adding the entries before multiplying.'
  elif l==2:
   C=M([[a,1],[0,b]]);D=M([[1,0],[d,1]]);f=[(C*D)[0,0]];q=f'A student multiplies corresponding entries to obtain the first entry of CD for C={L(C)}, D={L(D)}. Explain the error and calculate only the top-left entry.';ans=L(f[0]);steps=[f'Use the first row of C and first column of D, not corresponding positions in both matrices.',f'The entry is {a} times 1 plus 1 times {d} = {ans}.'];hints=['Choose a row and a column.','The entry is a sum of products.'];mistake='Using an entrywise product.'
  elif l==3:
   f=[A*B];q=f'Calculate AB for A={L(A)} and B={L(B)}. State the dimensions of the result.';ans=L(f[0]);steps=[f'A has size 2 by 3 and B has size 3 by 2, so AB has size 2 by 2.',f'Each entry is a row-column product. The two rows are {L(f[0][0,:])} and {L(f[0][1,:])}.',f'Hence AB={ans}.'];hints=['Check the shared dimension.','Calculate each row-column dot product.'];mistake='Using the outer dimensions in reverse order.'
  elif l==4:
   C=M([[a,1],[1,b]]);P=M([[d,-a]]);Q=P*C;f=[P];q=f'An unknown row matrix X satisfies X{L(C)}={L(Q)}. Recover X using two scalar equations and verify the product.';ans=L(P);steps=[f'Write X=(x,y). Multiplication gives {a}x+y={Q[0,0]} and x+{b}y={Q[0,1]}.',f'Eliminate y to get ({a*b-1})x={b*Q[0,0]-Q[0,1]}; x={d}, y={-a}.',f'The unique row {ans} gives {L(Q)} on multiplication.'];hints=['Write each product entry as an equation.','Eliminate one unknown and substitute back.'];mistake='Treating the row as a column or reversing multiplication.'
  elif l==5:
   C=M([[1,0,a],[0,1,b]]);D=M([[1-a*d,-a],[ -b*d,1-b],[d,1]]);f=[D,D*C];q=f'Given C={L(C)} find all entries in the top two rows of a 3 by 2 matrix X whose last row is ({d},1) and for which CX=I_2. Compute XC and decide whether it equals I_3.';ans=f'X={L(D)}; XC={L(D*C)}, not I_3.';steps=[f'Write the first two rows as unknowns. The first row of CX is row 1 of X plus {a} times row 3; the second is row 2 plus {b} times row 3.',f'Equate these to (1,0) and (0,1). This forces X={L(D)} and gives CX=I_2.',f'Multiplying in reverse order gives XC={L(D*C)}. Its last row starts with {d}, not zero, so XC is not I_3.'];hints=['Compute the two rows of CX symbolically.','Check the reversed product separately.'];mistake='Assuming a one-sided identity implies the reversed product is also an identity.'
  else:
   C=M([[1,0,a],[0,1,b]]);D=M([[1-a*u,-a*w],[-b*u,1-b*w],[u,w]]);N=M([-a,-b,1]);f=[D,N,D*C];q=f'For C={L(C)}, find every real 3 by 2 matrix X satisfying CX=I_2. Prove none can satisfy XC=I_3. Prove that (XC)^2=XC for every solution.';ans=f'X={L(D)} for arbitrary real u,w; XC is never I_3 but is idempotent.';steps=['Let the last row of X be (u,w). Multiplying C by X and comparing both rows with I_2 fixes the first two rows.',f'This forces X={L(D)}, and substitution gives CX=I_2 for all real u,w.',f'The nonzero vector n={L(N)} satisfies Cn=0. Consequently XCn=0 for every X, whereas I_3 n=n, so XC cannot equal I_3.', 'Associativity gives (XC)^2=X(CX)C=XI_2C=XC. The freely chosen last row accounts for every possible X, establishing completeness.'];hints=['Use the last row as two free parameters.','Find a nonzero vector killed by C; use associativity for the last identity.'];mistake='Cancelling a rectangular matrix as though it had a two-sided inverse.'
 elif path=='vector-combinations':
  A=M([a,-b,d]);B=M([1,d,-a]);P=M([1,2,3])
  if l==1:
   f=[-a+2*b];q=f'Calculate $-{a}+2({b})$.';ans=L(f[0]);steps=[f'Multiply first to obtain {2*b}, then add -{a}: {ans}.'];hints=['Use multiplication before addition.','Keep the negative sign.'];mistake='Adding before multiplying.'
  elif l==2:
   f=[a*A];q=f'A student scales the vector {L(A)} by {a} but changes only its first component. Explain the error and give the correct scaled vector.';ans=L(f[0]);steps=['Scalar multiplication changes every component by the same factor.',f'The result is {ans}, preserving the direction because the factor is positive.'];hints=['Scale all three coordinates.','Check the signs of the components.'];mistake='Multiplying only one component.'
  elif l==3:
   f=[2*A-3*B];q=f'Calculate 2u-3v for u={L(A)} and v={L(B)}.';ans=L(f[0]);steps=[f'Scale separately: 2u={L(2*A)}, 3v={L(3*B)}.',f'Subtract corresponding components: {ans}.'];hints=['Scale each vector separately.','Subtract the three corresponding components.'];mistake='Distributing the minus sign to only one component.'
  elif l==4:
   Q=P+A;R=P+B;S=P+A+B;mid=(P+S)/2;f=[S,mid];q=f'P={L(P)}, Q={L(Q)}, R={L(R)} are three vertices of a parallelogram, with Q and R adjacent to P. Find the fourth vertex S and verify the diagonals bisect each other.';ans=f'S={L(S)}; midpoint {L(mid)}.';steps=[f'The displacement from P to Q is {L(A)} and from P to R is {L(B)}.',f'Add both displacements to P, obtaining S={L(S)}.',f'Both (P+S)/2 and (Q+R)/2 equal {L(mid)}. The adjacent edge vectors are not proportional, so this is a nondegenerate parallelogram.'];hints=['Subtract the position of P from Q and R.','Compare the two diagonal midpoints.'];mistake='Adding position vectors without subtracting the common starting vertex.'
  elif l==5:
   Q=P+A;T=P+s.Rational(1,b)*A;f=[s.Rational(1,b),T,s.Rational(1,b-1)];q=f'P={L(P)} and Q={L(Q)}. A point T lies on the segment PQ and has first coordinate {L(T[0])}. Find T and the ratio PT:TQ. Verify that the result is interior.';ans=f'T={L(T)}, PT:TQ=1:{b-1}.';steps=[f'Write T=P+t(Q-P)={L(P+t*A)} with 0≤t≤1.',f'The first coordinate gives 1+{a}t={L(T[0])}; t=1/{b}.',f'Thus T={L(T)} and PT:TQ=1:{b-1}. Since 0<1/{b}<1, T lies strictly inside the segment; the nonzero first component fixes λ uniquely.'];hints=['Express the point using a single segment parameter.','The ratio is t:(1-t), not t:1.'];mistake='Confusing the fraction of the entire segment with the ratio of its two parts.'
  else:
   U=M([a,0,1]);V=M([0,b,1]);W=M([h,k,z]);p=h/a;qv=k/b;f=[p,qv,p+qv,1-p-qv];q=f'Let O be the origin, U={L(U)}, V={L(V)}. For all real h,k,z, determine exactly when W={L(W)} lies in the closed triangle OUV, including its edges. Give the coefficients of O,U,V in a convex combination (nonnegative coefficients summing to one), distinguish interior from boundary and prove uniqueness.';ans=f'z={L(p+qv)}, h≥0, k≥0, {L(p+qv)}≤1; coefficients {L(1-p-qv)}, {L(p)}, {L(qv)}. Interior iff all three are positive.';steps=['A point in the closed triangle is (1-α-β)O+αU+βV with α≥0, β≥0 and α+β≤1.',f'The first two components force α={L(p)}, β={L(qv)}; the third requires z={L(p+qv)}.',f'Consequently the three coefficients are {L(1-p-qv)}, {L(p)}, {L(qv)}; all must be nonnegative. If these conditions hold, the combination reconstructs W.', 'Strict positivity gives the interior relative to the triangle plane. At least one zero coefficient places W on an edge (including vertices). Since the first two components determine α,β uniquely, this covers every point and no others.'];hints=['Express W using the two edge vectors from O.','The third coordinate checks the plane; nonnegative coefficients check the triangle.'];mistake='Checking the plane equation but not the nonnegative coefficient conditions.'
 elif path=='perpendicular-test':
  A=M([a,b,0]);B=M([b,-a,d]);P=M([1,2,3])
  if l==1:
   C=M([1,-a,b]);D=M([d,b,2]);f=[C.dot(D)];q=f'Find the scalar product of {L(C)} and {L(D)}.';ans=L(f[0]);steps=[f'Multiply corresponding components and add: {d}-{a*b}+{2*b}={ans}.'];hints=['Use all three components.','Add the signed products.'];mistake='Multiplying the magnitudes instead of corresponding components.'
  elif l==2:
   f=[0,False];q=f'A student says the zero vector forms a right angle with {L(A)} because their scalar product is zero. Explain the error.';ans='The scalar product is zero, but the angle is undefined.';steps=['The zero vector has no direction and its magnitude is zero.', 'The angle formula divides by the product of magnitudes, so no angle is defined. Two nonzero vectors with zero scalar product are perpendicular.'];hints=['What is the magnitude of the zero vector?','Can the angle formula be used?'];mistake='Ignoring the nonzero requirement when defining an angle.'
  elif l==3:
   C=B+M([1,0,0]);f=[A.dot(B),A.dot(C)];q=f'Which of {L(B)} and {L(C)} is perpendicular to {L(A)}? Justify using both scalar products.';ans=f'Only {L(B)}.';steps=[f'The first scalar product is {L(f[0])}; the second is {L(f[1])}.','All vectors are nonzero, so only the first candidate is perpendicular.'];hints=['Compute each scalar product independently.','Check that both magnitudes are nonzero.'];mistake='Assuming visually similar vectors are both perpendicular.'
  elif l==4:
   Q=P+A;R=P+B;f=[A.dot(B),(-A).dot(B-A),(-B).dot(A-B)];q=f'Triangle PQR has vertices P={L(P)}, Q={L(Q)}, R={L(R)}. Determine whether it has a right angle and identify the vertex, using scalar products at all three vertices.';ans='Exactly one right angle, at P.';steps=[f'At P use PQ={L(A)} and PR={L(B)}: scalar product {f[0]}.',f'At Q use QP and QR: scalar product {f[1]}.',f'At R use RP and RQ: scalar product {f[2]}. All sides are nonzero; only the first dot product vanishes, so the right angle is at P.'];hints=['Use two vectors starting at each vertex.','Check all three scalar products.'];mistake='Using position vectors rather than displacement vectors at the vertex.'
  elif l==5:
   C=M([a,1,0]);D=M([0,b,1]);W=M([s.Rational(d,a*b),-s.Rational(d,b),d]);f=[W];q=f'Find every vector with third component {d} perpendicular to both {L(C)} and {L(D)}. Verify perpendicularity and prove uniqueness.';ans=L(W);steps=[f'Write W=(x,y,{d}). The two perpendicularity equations are {a}x+y=0 and {b}y+{d}=0.',f'The second forces y={L(W[1])}; the first forces x={L(W[0])}.',f'The resulting vector {ans} has zero scalar product with both given vectors and is nonzero because its third component is {d}. Each scalar equation determines one unknown uniquely.'];hints=['Write the two zero-dot-product equations.','Solve for y first, then x.'];mistake='Finding only one perpendicularity condition or allowing a zero direction.'
  else:
   C=M([h,k,0]);D=M([k-a,h-b,0]);K=a*h/(2*h-b);f=[K,s.Rational(b,2),M([0,0]),M([b,a])];q=f'For every real h,k, determine exactly when the nonzero vectors u={L(C)} and v={L(D)} form a right angle. Express k in terms of h, identify every forbidden h and every excluded pair, and prove that your classification is exhaustive.';ans=f'k={L(K)}, h≠{L(s.Rational(b,2))}, excluding (0,0) and ({b},{a}).';steps=[f'The scalar product is {L(s.expand(C.dot(D)))}. A right angle requires it to vanish with both vectors nonzero.',f'Rearrange to (2h-{b})k={a}h. If h={L(s.Rational(b,2))}, the left side is zero but the right side is {L(s.Rational(a*b,2))}, which is nonzero.',f'For every other h the unique possible k is {L(K)}.',f'The first vector vanishes only at (0,0); the second only at ({b},{a}). Both lie on the algebraic zero-product locus but must be excluded.', 'All other pairs on the displayed locus have nonzero vectors and zero scalar product, which is sufficient for a right angle. The exceptional denominator and zero-vector cases exhaust all exclusions.'];hints=['Expand the dot product and collect k terms.','Before dividing, check the zero coefficient; then exclude both zero-vector cases.'];mistake='Counting a zero vector as a perpendicular direction or dividing by a possibly zero coefficient.'
 else:raise ValueError(path)
 def enc(e):
  if type(e) is bool:return e
  if isinstance(e,s.MatrixBase):return {'matrix':[[str(x) for x in row] for row in e.tolist()]}
  return str(e)
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hints,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[enc(e) for e in f],likely_mistake=mistake,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
